//! Raw FFI bindings to [mlx-c] v0.7.0 (`a341b49`), linked statically together with MLX v0.32.4
//! (`36969c0`).
//!
//! Everything here is `unsafe` and mirrors the C API one to one; the safe layer lives in
//! `mrun-engine::mlx` (feature `mlx`). `src/bindings.rs` is generated by `regen.sh` and checked
//! in, so building this crate needs CMake and a C++ toolchain but no libclang.
//!
//! On macOS the build also produces `mlx.metallib`; its path is exported to dependants as
//! `DEP_MLXC_METALLIB` and the file is copied next to the binaries in the target directory.
//!
//! [mlx-c]: https://github.com/ml-explore/mlx-c

#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    unsafe_op_in_unsafe_fn,
    missing_debug_implementations,
    clippy::all
)]

include!("bindings.rs");
